function decodeNewsHtml(value) {
  return String(value ?? "")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&#39;/g, "'")
    .replace(/&rsquo;/g, "'")
    .replace(/&ldquo;/g, '"')
    .replace(/&rdquo;/g, '"')
    .replace(/&ndash;/g, "-")
    .replace(/&mdash;/g, "-")
    .replace(/&hellip;/g, "...")
    .replace(/&nbsp;/g, " ");
}

function stripNewsTags(value) {
  return decodeNewsHtml(String(value ?? "").replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim();
}

function stripNewsArticleHtml(value) {
  return decodeNewsHtml(String(value ?? ""))
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/(p|div|h[1-6]|li|ul|ol)>/gi, "\n")
    .replace(/<li[^>]*>/gi, "- ")
    .replace(/<[^>]+>/g, " ")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n[ \t]+/g, "\n")
    .replace(/[ \t]{2,}/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function chunkNewsText(value, chunkSize = 4800) {
  const text = String(value ?? "").trim();
  const chunks = [];

  for (let start = 0; start < text.length; start += chunkSize) {
    chunks.push(text.slice(start, start + chunkSize));
  }

  return chunks;
}

function getNewsCategory(title, fallback) {
  const normalized = String(title ?? "").toLowerCase();

  if (normalized.includes("hotfix")) return "hotfix";
  if (fallback === "patch" || normalized.includes("alpha ") || normalized.includes("patch notes")) return "patch";
  if (normalized.includes("roadmap")) return "roadmap";
  if (normalized.includes("this week in star citizen")) return "weekly";
  if (normalized.includes("monthly report")) return "report";
  if (
    normalized.includes("pirate week") ||
    normalized.includes("iae") ||
    normalized.includes("luminalia") ||
    normalized.includes("coramor") ||
    normalized.includes("red festival") ||
    normalized.includes("stella fortuna") ||
    normalized.includes("invictus") ||
    normalized.includes("alien week") ||
    normalized.includes("foundation festival")
  ) {
    return "event";
  }

  return fallback;
}

function getNewsCategoryZh(category) {
  return (
    {
      patch: "版本更新",
      hotfix: "热修",
      event: "活动",
      roadmap: "路线图",
      weekly: "周报",
      report: "报告",
      official: "官方公告",
    }[category] ?? "官方公告"
  );
}

function localizeNewsTitle(title, category) {
  const replacements = [
    [/This Week in Star Citizen/i, "本周星际公民"],
    [/Roadmap Roundup/i, "路线图汇总"],
    [/Star Citizen Monthly Report/i, "星际公民月度报告"],
    [/Monthly Report/i, "月度报告"],
    [/Pirate Week/i, "海盗周"],
    [/Luminalia/i, "光灯节"],
    [/Coramor/i, "科拉爱人节"],
    [/Red Festival/i, "火红节"],
    [/Stella Fortuna/i, "幸运星节"],
    [/Invictus Launch Week|ILW/i, "舰队周"],
    [/Alien Week/i, "外星周"],
    [/Foundation Festival/i, "奠基节"],
    [/Subscriber Promotions/i, "订阅者促销"],
    [/Jump Point Now Available/i, "Jump Point 杂志已发布"],
    [/Letter From The Chairman/i, "主席来信"],
    [/Improving The Live Experience/i, "改善线上体验"],
    [/Patch Notes/i, "补丁说明"],
    [/Hotfix/i, "热修"],
  ];

  const translated = replacements.reduce((value, [pattern, replacement]) => value.replace(pattern, replacement), title);

  if (translated !== title) return translated;
  if (category === "patch") return `版本更新：${title}`;
  if (category === "hotfix") return `热修：${title}`;
  if (category === "official") return `官方公告：${title}`;
  return title;
}

function localizeNewsSummary(summary, category) {
  if (!summary) return `${getNewsCategoryZh(category)}新闻，点击查看官方原文。`;
  if (category === "patch") return "版本补丁说明，建议查看原文确认具体改动。";
  if (category === "hotfix") return "热修说明，通常包含临时修复和线上问题处理。";
  if (category === "event") return "官方活动新闻，包含活动时间、奖励或商店内容。";
  if (category === "roadmap") return "路线图更新，包含开发进度和计划调整。";
  if (category === "weekly") return "官方周报，汇总本周活动和公告。";
  if (category === "report") return "官方月报，汇总各团队开发进展。";
  return "官方公告，点击查看原文。";
}

function getNewsTitleFromHref(href) {
  const slug = String(href ?? "").split("/").filter(Boolean).pop() || href;
  return decodeURIComponent(String(slug).replace(/^\d+-/, "").replace(/-/g, " "));
}

function parseNewsCardText(text, href) {
  const fallbackTitle = getNewsTitleFromHref(href);
  const compact = String(text ?? "").replace(/^(post|patchnotes)\s+/i, "").replace(/\s+/g, " ").trim();
  const parts = compact.match(/^(.*?)\s+\d+\s+Posted:\s+(.+)$/i);

  if (!parts) {
    return {
      title: fallbackTitle,
      posted: "",
      summary: "",
    };
  }

  const postedMatch = parts[2].match(/^((?:\d+\s+)?(?:minute|hour|day|week|month|year)s?\s+ago|today|yesterday)\s*(.*)$/i);

  return {
    title: parts[1].trim() || fallbackTitle,
    posted: postedMatch?.[1] ?? "",
    summary: postedMatch?.[2]?.trim() ?? "",
  };
}

async function fetchNewsFeed(feed) {
  const response = await fetch(feed.url, {
    headers: {
      "user-agent": "ENIGMA Ledger news index/1.0",
    },
    cf: {
      cacheTtl: 900,
      cacheEverything: false,
    },
  });

  if (!response.ok) throw new Error(`${feed.id} ${response.status}`);

  const html = await response.text();
  const matches = Array.from(html.matchAll(/<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g));
  const seen = new Set();
  const items = [];

  for (const match of matches) {
    const href = match[1];

    if (!href.includes("/comm-link/") || href.includes("{$")) continue;

    const url = href.startsWith("http") ? href : `${RSI_BASE_URL}${href}`;
    const text = stripNewsTags(match[2]);

    if (!text || seen.has(url)) continue;

    seen.add(url);

    const parsed = parseNewsCardText(text, href);
    const category = getNewsCategory(parsed.title, feed.defaultCategory);

    items.push({
      id: `${feed.id}:${href}`,
      title: parsed.title,
      titleZh: localizeNewsTitle(parsed.title, category),
      category,
      categoryZh: getNewsCategoryZh(category),
      sourceName: feed.name,
      sourceUrl: feed.url,
      url,
      posted: parsed.posted,
      summary: parsed.summary,
      summaryZh: localizeNewsSummary(parsed.summary, category),
    });

    if (items.length >= (feed.id === "patch-notes" ? 10 : 16)) break;
  }

  return items;
}

async function fetchOfficialArticleBody(url) {
  const pageResponse = await fetch(url, {
    headers: { "user-agent": "ENIGMA Ledger news index/1.0" },
    cf: { cacheTtl: 3600, cacheEverything: false },
  });

  if (!pageResponse.ok) return "";

  const pageHtml = await pageResponse.text();
  const bodyUrlMatch = pageHtml.match(/const\s+s3Url\s*=\s*'([^']+)'/);

  if (!bodyUrlMatch?.[1]) return "";

  const bodyUrl = bodyUrlMatch[1].startsWith("http") ? bodyUrlMatch[1] : `${RSI_BASE_URL}${bodyUrlMatch[1]}`;
  const bodyResponse = await fetch(bodyUrl, {
    headers: { "user-agent": "ENIGMA Ledger news index/1.0" },
    cf: { cacheTtl: 3600, cacheEverything: false },
  });

  if (!bodyResponse.ok) return "";

  const bodyHtml = await bodyResponse.text();
  const articleBodies = Array.from(bodyHtml.matchAll(/<g-article\b[^>]*\sbody="([\s\S]*?)"/g))
    .map((match) => stripNewsArticleHtml(match[1]))
    .filter(Boolean)
    .sort((left, right) => right.length - left.length);

  return articleBodies[0] ?? "";
}

async function hydrateLatestPatchArticle(items) {
  const hydrated = items.map((item) => ({ ...item }));
  const patchIndex = hydrated.findIndex((item) => item.category === "patch");

  if (patchIndex < 0) return hydrated;

  try {
    const content = await fetchOfficialArticleBody(hydrated[patchIndex].url);

    if (content) {
      hydrated[patchIndex].content = content;
      hydrated[patchIndex].contentZh = "";
      hydrated[patchIndex].contentMode = "full_patch";
    }
  } catch {
    // Keep the feed usable when RSI's article body endpoint changes.
  }

  return hydrated;
}

function getNewsTranslationConfig(env, request, url) {
  const provider = env.NEWS_TRANSLATION_PROVIDER || "none";
  const requested = url.searchParams.get("translate") === "1";
  const providedSecret = request.headers.get("x-enigma-sync-secret") || url.searchParams.get("secret");
  const authorized = Boolean(requested && env.NEWS_SYNC_SECRET && providedSecret === env.NEWS_SYNC_SECRET);
  const enabled =
    provider === "google"
      ? Boolean(env.GOOGLE_TRANSLATE_API_KEY)
      : provider === "microsoft"
        ? Boolean(env.MICROSOFT_TRANSLATOR_KEY && env.MICROSOFT_TRANSLATOR_REGION)
        : false;

  return {
    enabled,
    provider,
    requested,
    authorized,
    translatedItems: 0,
    usedCharacters: 0,
    maxArticlesPerRun: Math.min(20, Math.max(0, Number(env.NEWS_TRANSLATION_MAX_ARTICLES_PER_RUN || 3))),
    maxCharactersPerArticle: Math.min(12000, Math.max(0, Number(env.NEWS_TRANSLATION_MAX_CHARS_PER_ARTICLE || 3000))),
    maxCharactersPerPatch: Math.min(80000, Math.max(0, Number(env.NEWS_TRANSLATION_MAX_PATCH_CHARS || 50000))),
    maxCharactersPerRun: Math.min(100000, Math.max(0, Number(env.NEWS_TRANSLATION_MAX_CHARS_PER_RUN || 9000))),
    message: "Public read only. Translation not requested.",
  };
}

async function translateNewsTexts(env, provider, texts) {
  if (provider === "google") {
    const response = await fetch(`https://translation.googleapis.com/language/translate/v2?key=${env.GOOGLE_TRANSLATE_API_KEY}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ q: texts, source: "en", target: "zh-CN", format: "text" }),
    });

    if (!response.ok) throw new Error(`Google Translate ${response.status}`);
    const payload = await response.json();
    return payload?.data?.translations?.map((translation) => decodeNewsHtml(translation.translatedText || "")) || texts;
  }

  if (provider === "microsoft") {
    const endpoint = env.MICROSOFT_TRANSLATOR_ENDPOINT || "https://api.cognitive.microsofttranslator.com";
    const response = await fetch(`${endpoint}/translate?api-version=3.0&from=en&to=zh-Hans`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "ocp-apim-subscription-key": env.MICROSOFT_TRANSLATOR_KEY || "",
        "ocp-apim-subscription-region": env.MICROSOFT_TRANSLATOR_REGION || "",
      },
      body: JSON.stringify(texts.map((text) => ({ Text: text }))),
    });

    if (!response.ok) throw new Error(`Microsoft Translator ${response.status}`);
    const payload = await response.json();
    return payload.map((item, index) => item?.translations?.[0]?.text || texts[index]);
  }

  return texts;
}

async function applyNewsTranslation(items, env, request, url) {
  const meta = getNewsTranslationConfig(env, request, url);

  if (!meta.requested) return { items, meta };
  if (!meta.authorized) return { items, meta: { ...meta, message: "Translation request denied. Missing or invalid sync secret." } };
  if (!meta.enabled) return { items, meta: { ...meta, message: "Translation provider is not configured." } };

  const textPairs = [];
  let usedCharacters = 0;
  const runLimit = Math.max(meta.maxCharactersPerRun, meta.maxCharactersPerPatch);

  const addTextPair = (itemIndex, field, value, append = false, limit = meta.maxCharactersPerArticle) => {
    const text = String(value || "").slice(0, limit).trim();
    if (!text || usedCharacters + text.length > runLimit) return false;
    usedCharacters += text.length;
    textPairs.push({ itemIndex, field, text, append });
    return true;
  };

  const latestPatchIndex = items.findIndex((item) => item.category === "patch" && item.content);
  const latestPatch = latestPatchIndex >= 0 ? items[latestPatchIndex] : null;

  if (latestPatch) {
    addTextPair(latestPatchIndex, "titleZh", latestPatch.title);

    for (const chunk of chunkNewsText(String(latestPatch.content).slice(0, meta.maxCharactersPerPatch))) {
      if (!addTextPair(latestPatchIndex, "contentZh", chunk, true, chunk.length)) break;
    }
  }

  items.slice(0, meta.maxArticlesPerRun).forEach((item, itemIndex) => {
    if (itemIndex === latestPatchIndex) return;

    [
      ["titleZh", item.title],
      ["summaryZh", item.summary || item.title],
    ].forEach(([field, value]) => {
      addTextPair(itemIndex, field, value);
    });
  });

  if (!textPairs.length) return { items, meta: { ...meta, message: "Translation skipped. Character limit reached or no text." } };

  try {
    const translations = await translateNewsTexts(env, meta.provider, textPairs.map((pair) => pair.text));
    const translatedItems = items.map((item) => ({ ...item }));

    textPairs.forEach((pair, index) => {
      if (pair.append) {
        translatedItems[pair.itemIndex][pair.field] = [translatedItems[pair.itemIndex][pair.field], translations[index]]
          .filter(Boolean)
          .join("\n\n");
      } else {
        translatedItems[pair.itemIndex][pair.field] = translations[index] || translatedItems[pair.itemIndex][pair.field];
      }
      translatedItems[pair.itemIndex].translatedBy = meta.provider;
    });

    return {
      items: translatedItems,
      meta: {
        ...meta,
        translatedItems: new Set(textPairs.map((pair) => pair.itemIndex)).size,
        usedCharacters,
        message: "Translation completed within per-run limits.",
      },
    };
  } catch {
    return { items, meta: { ...meta, usedCharacters, message: "Translation provider failed. Fallback text returned." } };
  }
}

async function readCachedNewsResponse() {
  if (typeof caches === "undefined") return null;

  const cached = await caches.default.match(new Request(NEWS_CACHE_URL));
  return cached ? withSecurityHeaders(cached) : null;
}

async function writeCachedNewsResponse(response) {
  if (typeof caches === "undefined") return;

  const headers = new Headers(response.headers);
  headers.set("cache-control", "public, max-age=86400");

  await caches.default.put(
    new Request(NEWS_CACHE_URL),
    new Response(response.clone().body, {
      status: response.status,
      statusText: response.statusText,
      headers,
    }),
  );
}

async function handleNewsApi(request, env, url) {
  if (request.method !== "GET") {
    return jsonResponse({ error: "Method not allowed." }, { status: 405, headers: { allow: "GET" } });
  }

  if (url.searchParams.get("translate") !== "1") {
    const cached = await readCachedNewsResponse();
    if (cached) return cached;
  }

  const rateLimit = rateLimitRequest(request, "news", 60, 60);
  if (!rateLimit.allowed) {
    return jsonResponse({ error: "Rate limit exceeded." }, { status: 429 });
  }

  const results = await Promise.allSettled(NEWS_FEEDS.map(fetchNewsFeed));
  const feedItems = results.flatMap((result) => (result.status === "fulfilled" ? result.value : []));
  const items = await hydrateLatestPatchArticle(feedItems);
  const translated = await applyNewsTranslation(items, env, request, url);

  const response = jsonResponse({
    data: translated.items,
    meta: {
      count: translated.items.length,
      source: "RSI official",
      updatedAt: new Date().toISOString(),
      translation: translated.meta,
      providers: results.map((result, index) => ({
        id: NEWS_FEEDS[index].id,
        status: result.status,
        url: NEWS_FEEDS[index].url,
      })),
    },
  });

  if (translated.meta.authorized && translated.meta.translatedItems > 0) {
    await writeCachedNewsResponse(response);
  }

  return response;
}

function handleHealthApi(request) {
  if (request.method !== "GET") {
    return jsonResponse({ error: "Method not allowed." }, { status: 405, headers: { allow: "GET" } });
  }

  return jsonResponse({
    ok: true,
    service: "ENIGMA Verse Index",
    runtime: "cloudflare-worker",
    checks: {
      searchRecords: ENIGMA_DATA.searchRecords.length,
      tradeRoutes: ENIGMA_DATA.tradeRoutes.length,
      sourceCatalog: ENIGMA_DATA.sourceCatalog.length,
      uexTradeLocations: getStaticUexTradeTerminals().length,
    },
  });
}

function parseKookCommand(content) {
  const raw = content.trim();

  if (!raw.startsWith("/") && !raw.startsWith("!")) {
    return null;
  }

  const [commandName = "", ...args] = raw.slice(1).split(/\s+/).filter(Boolean);
  const aliases = {
    h: "help",
    help: "help",
    s: "search",
    search: "search",
    ship: "ship",
    ships: "ship",
    item: "item",
    i: "item",
    price: "price",
    p: "price",
    route: "route",
    r: "route",
  };

  return { name: aliases[commandName.toLowerCase()] ?? "unknown", args, raw };
}

function formatKookSearchReply(command) {
  const query = command.args.join(" ").trim();

  if (!query) {
    return "Input a query, for example: /ship C2 or /price Gold.";
  }

  const type = command.name === "ship" ? "ship" : command.name === "price" ? "commodity" : "all";
  const results = searchLocalRecords({ query, type, freshness: "all", limit: 3 });

  if (!results.length) {
    return `No local result found: ${query}`;
  }

  return results
    .map((record, index) =>
      [`${index + 1}. ${record.name}${record.nameZh ? ` / ${record.nameZh}` : ""}`, record.summary, record.source.sourceName].join(
        "\n",
      ),
    )
    .join("\n\n");
}

function formatKookRouteReply(command) {
  const routes = calculateTradeRoutes({
    origin: "Seraphim Station",
    cargoScu: command.args[0] ?? 696,
    budgetUec: command.args[1] ?? 750000,
    limit: 3,
  });

  if (!routes.length) {
    return "No profitable local route found for this cargo and budget.";
  }

  return routes
    .map(
      (route, index) =>
        `${index + 1}. ${route.commodity}: ${route.buyTerminal} -> ${route.sellTerminal}\n${route.purchasableScu} SCU / ${route.totalProfit.toLocaleString("en-US")} UEC`,
    )
    .join("\n\n");
}

async function sendKookChannelMessage(env, targetId, content, quoteMessageId) {
  if (!env.KOOK_BOT_TOKEN) {
    return { skipped: true, reason: "KOOK_BOT_TOKEN not configured." };
  }

  const apiBase = env.KOOK_API_BASE_URL ?? "https://www.kookapp.cn/api/v3";
  const response = await fetch(`${apiBase}/message/create`, {
    method: "POST",
    headers: {
      authorization: `Bot ${env.KOOK_BOT_TOKEN}`,
      "content-type": "application/json",
    },
    body: JSON.stringify({
      type: 9,
      target_id: targetId,
      content: content.slice(0, 1800),
      quote: quoteMessageId,
    }),
  });

  if (!response.ok) {
    throw new Error(`KOOK message send failed: ${response.status}`);
  }

  return response.json();
}

async function handleKookWebhook(request, env) {
  if (request.method === "GET") {
    return jsonResponse({
      ok: true,
      service: "ENIGMA KOOK webhook",
      configured: Boolean(env.KOOK_VERIFY_TOKEN && env.KOOK_BOT_TOKEN),
    });
  }

  if (request.method !== "POST") {
    return jsonResponse({ error: "Method not allowed." }, { status: 405, headers: { allow: "GET, POST" } });
  }

  const rawBody = await request.text();

  if (rawBody.length > 256 * 1024) {
    return jsonResponse({ error: "Payload too large." }, { status: 413 });
  }

  let envelope;

  try {
    envelope = JSON.parse(rawBody);
  } catch {
    return jsonResponse({ error: "Invalid KOOK payload." }, { status: 400 });
  }

  if (env.KOOK_VERIFY_TOKEN && envelope.d?.verify_token !== env.KOOK_VERIFY_TOKEN) {
    return jsonResponse({ error: "Invalid verify token." }, { status: 401 });
  }

  if (envelope.d?.challenge) {
    return jsonResponse({ challenge: envelope.d.challenge });
  }

  const event = envelope.d;

  if (!event || event.extra?.author?.bot || !event.target_id) {
    return jsonResponse({ ok: true, ignored: true });
  }

  const command = parseKookCommand(event.content ?? "");

  if (!command) {
    return jsonResponse({ ok: true, ignored: true });
  }

  const reply =
    command.name === "help"
      ? "ENIGMA Verse Index\n/search <query>\n/ship <ship>\n/item <item>\n/price <commodity>\n/route <cargoScu> <budgetUec>"
      : command.name === "route"
        ? formatKookRouteReply(command)
        : command.name === "search" || command.name === "ship" || command.name === "item" || command.name === "price"
          ? formatKookSearchReply(command)
          : "Unknown command. Use /help.";

  const sendResult = await sendKookChannelMessage(env, event.target_id, reply, event.msg_id);
  return jsonResponse({ ok: true, sent: !sendResult.skipped, sendResult });
}

async function fetchAsset(env, request, pathname) {
  const url = new URL(request.url);
  url.pathname = pathname;
  url.search = "";
  return env.ASSETS.fetch(new Request(url, request));
}

async function handleApi(request, env, url) {
  if (request.method === "OPTIONS") {
    return withSecurityHeaders(new Response(null, { status: 204 }));
  }

  if (url.pathname === "/api/health") {
    return handleHealthApi(request);
  }

  if (url.pathname === "/api/search") {
    return handleSearchApi(request, url);
  }

  if (url.pathname === "/api/sources") {
    return handleSourcesApi(request);
  }

  if (url.pathname === "/api/news") {
    return handleNewsApi(request, env, url);
  }

  if (url.pathname === "/api/trade/routes") {
    return handleTradeRoutesApi(request, env, url);
  }

  if (url.pathname === "/api/trade/locations") {
    return handleTradeLocationsApi(request, env, url);
  }

  if (url.pathname === "/api/trade/ships") {
    return handleTradeShipsApi(request, url);
  }

  if (url.pathname === "/api/kook/webhook") {
    return handleKookWebhook(request, env);
  }

  return jsonResponse({ error: "Not found." }, { status: 404 });
}

export default {
  async scheduled(_event, env, ctx) {
    ctx.waitUntil(getRuntimeLocalizationAliases(true));

    if (env.NEWS_SYNC_SECRET && env.NEWS_TRANSLATION_PROVIDER && env.NEWS_TRANSLATION_PROVIDER !== "none") {
      const url = new URL("https://enigmaledger.internal/api/news");
      url.searchParams.set("translate", "1");

      ctx.waitUntil(
        handleNewsApi(
          new Request(url, {
            headers: {
              "x-enigma-sync-secret": env.NEWS_SYNC_SECRET,
            },
          }),
          env,
          url,
        ),
      );
    }
  },

  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname.startsWith("/api/")) {
      return handleApi(request, env, url);
    }

    const response = await env.ASSETS.fetch(request);

    if (response.status !== 404 || !["GET", "HEAD"].includes(request.method)) {
      return withSecurityHeaders(response);
    }

    if (!acceptsHtml(request)) {
      return withSecurityHeaders(response);
    }

    if (!url.pathname.endsWith("/")) {
      const directoryIndex = await fetchAsset(env, request, `${url.pathname}/index.html`);

      if (directoryIndex.status !== 404) {
        return withSecurityHeaders(directoryIndex);
      }
    }

    const appShell = await fetchAsset(env, request, "/index.html");
    return withSecurityHeaders(appShell);
  },
};
